// Persistent IndexedDB archive for images generated by Solenoid (`generate_image`).
// Stored in IndexedDB rather than localStorage so high-resolution PNGs survive
// reloads without competing with the 5 MB localStorage quota.

import { writable } from 'svelte/store';

export interface GeneratedArtItem {
  id: string;
  title: string;
  prompt: string;
  modelLabel: string;
  aspectRatio?: string;
  dataUrl: string;
  createdAt: string;
}

const DB_NAME = 'radial-planner-art-v1';
const STORE_NAME = 'images';
const DB_VERSION = 1;

export const artGalleryItems = writable<GeneratedArtItem[]>([]);
let loadedOnce = false;

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(new Error('IndexedDB unavailable'));
      return;
    }
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error || new Error('Failed to open Art Gallery DB'));
  });
}

export async function loadArtGallery(force = false): Promise<GeneratedArtItem[]> {
  if (loadedOnce && !force) {
    let current: GeneratedArtItem[] = [];
    artGalleryItems.subscribe((v) => { current = v; })();
    return current;
  }
  try {
    const db = await openDb();
    const items = await new Promise<GeneratedArtItem[]>((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.getAll();
      req.onsuccess = () => resolve((req.result as GeneratedArtItem[]) || []);
      req.onerror = () => reject(req.error);
    });
    db.close();
    items.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
    loadedOnce = true;
    artGalleryItems.set(items);
    return items;
  } catch (err) {
    console.warn('[ArtGallery] Failed to load IndexedDB archive:', err);
    return [];
  }
}

export async function saveArtToGallery(
  input: Omit<GeneratedArtItem, 'id' | 'createdAt'>
): Promise<GeneratedArtItem> {
  const item: GeneratedArtItem = {
    ...input,
    id: 'art_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
    createdAt: new Date().toISOString(),
  };
  try {
    const db = await openDb();
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readwrite');
      tx.objectStore(STORE_NAME).put(item);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
    db.close();
  } catch (err) {
    console.warn('[ArtGallery] Failed to persist image in IndexedDB:', err);
  }
  artGalleryItems.update((list) => [item, ...list.filter((x) => x.id !== item.id)]);
  loadedOnce = true;
  return item;
}

export async function deleteArtFromGallery(id: string): Promise<void> {
  try {
    const db = await openDb();
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readwrite');
      tx.objectStore(STORE_NAME).delete(id);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
    db.close();
  } catch (err) {
    console.warn('[ArtGallery] Failed to delete image from IndexedDB:', err);
  }
  artGalleryItems.update((list) => list.filter((x) => x.id !== id));
}
